create table if not exists public.cp_commercial_tiers(id uuid primary key default gen_random_uuid(),audience text not null check(audience in('white_label','pf')),code text not null unique,name text not null,min_users integer not null check(min_users>=1),max_users integer,monthly_amount numeric(14,2),price_basis text not null,status_comercial text not null check(status_comercial in('disponivel_contratacao','sob_consulta','oculto','aguardando_preco_pf')),description text,sort_order integer not null default 0,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
