on conflict(code) do update set name=excluded.name,min_users=excluded.min_users,max_users=excluded.max_users,monthly_amount=excluded.monthly_amount,price_basis=excluded.price_basis,status_comercial=excluded.status_comercial,description=excluded.description,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
alter table public.cp_commercial_tiers enable row level security; revoke all on public.cp_commercial_tiers from anon; grant select on public.cp_commercial_tiers to authenticated; grant all on public.cp_commercial_tiers to service_role; drop policy if exists cp_commercial_tiers_read on public.cp_commercial_tiers; create policy cp_commercial_tiers_read on public.cp_commercial_tiers for select to authenticated using(true);
create table if not exists public.cp_invitations(id uuid primary key default gen_random_uuid(),inviter_user_id uuid not null references auth.users(id) on delete cascade,invited_phone_hash text not null,invitation_token_hash text not null unique,state text not null default 'invited' check(state in('invited','invitee_2fa_verified','invitee_accepted','inviter_confirmed','active','expired','revoked')),second_factor_type text,second_factor_verified_at timestamptz,invitee_user_id uuid references auth.users(id) on delete set null,invitee_accepted_at timestamptz,inviter_confirmed_at timestamptz,activated_at timestamptz,expires_at timestamptz not null default(now()+interval '72 hours'),revoked_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.cp_invitations enable row level security; revoke all on public.cp_invitations from anon; grant select,insert,update on public.cp_invitations to authenticated; grant all on public.cp_invitations to service_role; drop policy if exists cp_invitations_parties_read on public.cp_invitations; create policy cp_invitations_parties_read on public.cp_invitations for select to authenticated using(inviter_user_id=auth.uid() or invitee_user_id=auth.uid()); drop policy if exists cp_invitations_inviter_create on public.cp_invitations; create policy cp_invitations_inviter_create on public.cp_invitations for insert to authenticated with check(inviter_user_id=auth.uid());
create table if not exists public.cp_devices(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,device_public_id text not null,identity_public_key bytea not null,signed_prekey_public bytea,pq_prekey_public bytea,key_protocol text not null default 'planned:PQXDH+DoubleRatchet',hardware_backed_claim boolean not null default false,trusted_at timestamptz,revoked_at timestamptz,last_seen_at timestamptz,created_at timestamptz not null default now(),unique(user_id,device_public_id));
alter table public.cp_devices enable row level security; revoke all on public.cp_devices from anon; grant select,insert,update on public.cp_devices to authenticated; grant all on public.cp_devices to service_role; drop policy if exists cp_devices_own_manage on public.cp_devices; create policy cp_devices_own_manage on public.cp_devices for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create table if not exists public.cp_application_access_records(id uuid primary key default gen_random_uuid(),pseudonymous_account_ref text not null,accessed_at timestamptz not null default now(),source_ip inet not null,source_port integer,application_action text not null default 'session_access',integrity_hash text not null,legal_hold_until timestamptz,purge_after timestamptz not null default(now()+interval '6 months'),created_at timestamptz not null default now()); alter table public.cp_application_access_records enable row level security; revoke all on public.cp_application_access_records from anon,authenticated; grant all on public.cp_application_access_records to service_role;
create table if not exists public.cp_legal_requests(id uuid primary key default gen_random_uuid(),jurisdiction text not null,authority_name text not null,request_type text not null check(request_type in('preservation','access_records','subscriber_data','content','other')),legal_reference text,received_at timestamptz not null default now(),scope_summary text not null,response_status text not null default 'under_review',content_available_to_provider boolean not null default false,response_summary text,closed_at timestamptz,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now()); alter table public.cp_legal_requests enable row level security; revoke all on public.cp_legal_requests from anon,authenticated; grant all on public.cp_legal_requests to service_role;
create table if not exists public.cp_security_profile(id uuid primary key default gen_random_uuid(),version text not null unique,status text not null default 'draft' check(status in('draft','approved','active','retired')),e2ee_required boolean not null default true,provider_has_decryption_keys boolean not null default false check(provider_has_decryption_keys=false),content_backups_allowed boolean not null default false check(content_backups_allowed=false),metadata_minimization boolean not null default true,protocol_1to1 text not null default 'planned:PQXDH + Double Ratchet',protocol_groups text not null default 'planned:MLS RFC 9420',invite_only boolean not null default true,initial_2fa_required boolean not null default true,double_acceptance_required boolean not null default true,retention_options jsonb not null default '["manual","24h","48h","1d","2d","5d","30d"]'::jsonb,legal_access_log_months integer not null default 6,hosting_policy text not null default 'dedicated_cp_infrastructure_required',notes text,approved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now()); insert into public.cp_security_profile(version,status,notes) values('cp-security-v1','draft','Arquitetura alvo: conteúdo E2EE sem chaves privadas no servidor; armazenamento de payload dedicado sem backup recuperável; registros legais mínimos segregados. Não comercializar como homologado antes de auditoria criptográfica e E2E.') on conflict(version) do update set notes=excluded.notes,updated_at=now(); alter table public.cp_security_profile enable row level security; revoke all on public.cp_security_profile from anon; grant select on public.cp_security_profile to authenticated; grant all on public.cp_security_profile to service_role; drop policy if exists cp_security_profile_read on public.cp_security_profile; create policy cp_security_profile_read on public.cp_security_profile for select to authenticated using(status in('approved','active'));
alter table public.cp_messages add column if not exists payload_store text not null default 'legacy_primary_db'; alter table public.cp_messages add column if not exists purge_state text not null default 'not_due' check(purge_state in('not_due','due','purged','blocked_legal_hold')); alter table public.cp_messages add column if not exists legal_hold_until timestamptz; alter table public.cp_messages add column if not exists crypto_shredded_at timestamptz;
update public.modules set name='CP — Chat Privado',description='Comunicação privada por convite, com criptografia ponta a ponta, identidade pseudônima, retenção configurável e arquitetura de minimização de metadados.',category='privacy',status_tecnico='em_homologacao',status_comercial='sob_consulta',readiness_status='em_testes',show_on_site=true,show_in_checkout=false,show_in_plans=false,show_price=false,allow_standalone=true,cta_primary='Conhecer o CP',commercial_url='/cp',readiness_checklist=jsonb_build_object('e2ee_protocol_audit',false,'dedicated_payload_store_no_backup',false,'client_side_key_management',false,'double_acceptance_invites',false,'retention_hard_delete_e2e',false,'legal_access_log_6m',true,'external_security_audit',false,'mobile_device_hardening',false),updated_at=now() where slug='cp';